import * as T from '../vendor/three.module.js';
// Separate fixed pools keep persistent smoke from consuming the fire/spark budget.
export function createEffects(scene){
 const makePool=(capacity,additive)=>{
  const data=Array.from({length:capacity},()=>({life:0})),position=new Float32Array(capacity*3),color=new Float32Array(capacity*3),size=new Float32Array(capacity),alpha=new Float32Array(capacity),geometry=new T.BufferGeometry();
  for(const [name,array,itemSize]of [['position',position,3],['color',color,3],['size',size,1],['alpha',alpha,1]])geometry.setAttribute(name,new T.BufferAttribute(array,itemSize).setUsage(T.DynamicDrawUsage));
  const material=new T.ShaderMaterial({transparent:true,depthWrite:false,vertexColors:true,blending:additive?T.AdditiveBlending:T.NormalBlending,uniforms:{viewportScale:{value:400}},vertexShader:'uniform float viewportScale;attribute float size;attribute float alpha;varying vec3 vColor;varying float vAlpha;void main(){vColor=color;vAlpha=alpha;vec4 p=modelViewMatrix*vec4(position,1.);gl_Position=projectionMatrix*p;gl_PointSize=clamp(size*viewportScale/max(1.,-p.z),1.,240.);}',fragmentShader:'varying vec3 vColor;varying float vAlpha;void main(){vec2 uv=gl_PointCoord-.5;float r=length(uv)*2.;float turbulence=sin(uv.x*21.+sin(uv.y*17.))*sin(uv.y*19.);float edge=smoothstep(.26,1.,r+turbulence*.08);if(r>1.)discard;gl_FragColor=vec4(vColor,vAlpha*(1.-edge));}'});
  const mesh=new T.Points(geometry,material);mesh.frustumCulled=false;scene.add(mesh);return {data,position,color,size,alpha,geometry,material,mesh,cursor:0,active:false};
 };
 const fire=makePool(360,true),smoke=makePool(440,false);let shake=0,screenFlash=0,lightLife=0,lastDistance=35;
 const flash=new T.PointLight('#ff9e45',0,65,1.6);scene.add(flash);
 const rings=Array.from({length:5},()=>{const material=new T.MeshBasicMaterial({color:'#ffd6a1',transparent:true,opacity:0,depthWrite:false,side:T.DoubleSide,blending:T.AdditiveBlending});const mesh=new T.Mesh(new T.RingGeometry(.94,1,64),material);mesh.rotation.x=-Math.PI/2;mesh.visible=false;scene.add(mesh);return {mesh,life:0};});let ringCursor=0;
 const debris=new T.InstancedMesh(new T.BoxGeometry(1,1,1),new T.MeshStandardMaterial({color:'#3b3835',roughness:.9}),120),pieces=Array.from({length:120},()=>({life:0})),dummy=new T.Object3D();debris.frustumCulled=false;scene.add(debris);let debrisCursor=0,debrisActive=false;
 dummy.scale.setScalar(0);dummy.updateMatrix();for(let i=0;i<120;i++)debris.setMatrixAt(i,dummy.matrix);
 function emit(pool,p,color,size,life,vx=0,vy=0,vz=0,gravity=0,growth=1,opacity=1){const i=pool.cursor++%pool.data.length,q=pool.data[i];Object.assign(q,{x:p.x,y:p.y,z:p.z,vx,vy,vz,gravity,size,life,total:life,growth,opacity});pool.color.set(color,i*3);pool.active=true;}
 function explode(p,viewer,radius=7){const nuclear=radius>=100;lastDistance=viewer?Math.hypot(viewer.x-p.x,viewer.y-p.y,viewer.z-p.z):35;shake=Math.max(shake,Math.min(.9,22/Math.max(18,lastDistance)));screenFlash=Math.max(screenFlash,.24*Math.min(1,35/Math.max(1,lastDistance)));
  for(let i=0;i<130;i++){const a=Math.random()*Math.PI*2,u=Math.random()*2-1,v=3+Math.random()*20,q=Math.sqrt(1-u*u);emit(fire,p,i<55?[1,.45,.065]:[1,.86,.42],i<55?2+Math.random()*3:.12+Math.random()*.35,i<55?.6+Math.random()*.9:.7+Math.random()*1.2,Math.cos(a)*q*v,u*v+5,Math.sin(a)*q*v,i<55?2:14,i<55?3:.5);}
  for(let i=0;i<65;i++){const a=Math.random()*Math.PI*2,v=Math.random()*9;emit(smoke,p,[.18+Math.random()*.1,.19,.21],2+Math.random()*4,3.5+Math.random()*2.5,Math.cos(a)*v,2+Math.random()*7,Math.sin(a)*v,-.25,2.5,.82);}
  if(nuclear){for(let i=0;i<160;i++){const a=i*2.39996,r=15+Math.random()*30;emit(smoke,{x:p.x+Math.cos(a)*r,y:p.y+32+Math.random()*20,z:p.z+Math.sin(a)*r},[.29,.25,.22],16+Math.random()*15,7+Math.random()*3,Math.cos(a)*2,3,Math.sin(a)*2,0,1.2,.85);}for(let i=0;i<70;i++)emit(fire,{x:p.x+(Math.random()-.5)*35,y:p.y+Math.random()*45,z:p.z+(Math.random()-.5)*35},[1,.55,.12],12,2,0,8,0,0,2);shake=Math.max(shake,.9*Math.min(1,100/Math.max(1,lastDistance)));screenFlash=Math.max(screenFlash,.42*Math.min(1,120/Math.max(1,lastDistance)));}const ring=rings[ringCursor++%rings.length];ring.total=nuclear?3:.95;ring.radius=nuclear?100:25;ring.life=ring.total;ring.mesh.position.set(p.x,p.y+.12,p.z);ring.mesh.visible=true;flash.position.set(p.x,p.y+2,p.z);lightLife=.7;
  for(let i=0;i<30;i++){const a=Math.random()*Math.PI*2;Object.assign(pieces[debrisCursor++%120],{x:p.x,y:p.y+.1,z:p.z,vx:Math.cos(a)*(3+Math.random()*13),vy:5+Math.random()*15,vz:Math.sin(a)*(3+Math.random()*13),life:3.8,size:.18+Math.random()*.8,spin:Math.random()*7,floor:p.y-.1});}debrisActive=true;
 }
 function updatePool(pool,dt){if(!pool.active)return;let active=false;for(let i=0;i<pool.data.length;i++){const p=pool.data[i];p.life=Math.max(0,p.life-dt);if(p.life>0){active=true;p.vy-=p.gravity*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;const progress=1-p.life/p.total,k=i*3;pool.position[k]=p.x;pool.position[k+1]=p.y;pool.position[k+2]=p.z;pool.size[i]=p.size*(1+progress*p.growth);pool.alpha[i]=p.opacity*Math.min(1,p.life/.35)*(1-progress*.65);}else pool.alpha[i]=0;}pool.active=active;for(const name of ['position','color','size','alpha'])pool.geometry.attributes[name].needsUpdate=true;}
 return {get shake(){return shake;},get flash(){return screenFlash;},explode,
 impact(p,intensity){shake=Math.max(shake,Math.min(1,intensity/8+.15));for(let i=0;i<28;i++){const a=Math.random()*6.28;emit(fire,p,[1,.7,.2],.1+Math.random()*.3,.25+Math.random()*.5,Math.cos(a)*6,Math.random()*5,Math.sin(a)*6,10);}},
 launch(p){for(let i=0;i<14;i++)emit(fire,p,[1,.67,.19],.3+Math.random()*.5,.12+Math.random()*.18,(Math.random()-.5)*4,(Math.random()-.5)*4,(Math.random()-.5)*4);},
 trail(p){const speed=Math.hypot(p.vx||0,p.vy||0,p.vz||0)||1;for(let i=0;i<3;i++){const t=i/3*.035,at={x:p.x-(p.vx||0)*t,y:p.y-(p.vy||0)*t,z:p.z-(p.vz||0)*t};emit(smoke,at,[.61,.63,.66],.4,1.5,(Math.random()-.5)*.6,.4,(Math.random()-.5)*.6,0,4,.5);emit(fire,at,[1,.46,.08],.42,.17,-(p.vx||0)/speed*6,-(p.vy||0)/speed*6,-(p.vz||0)/speed*6,0,.3);}},
 render(camera,height){const scale=height/(2*Math.tan(camera.fov*Math.PI/360));fire.material.uniforms.viewportScale.value=smoke.material.uniforms.viewportScale.value=scale;},
 update(dt){shake*=Math.exp(-5*dt);screenFlash*=Math.exp(-9*dt);lightLife=Math.max(0,lightLife-dt);flash.intensity=lightLife*180;updatePool(fire,dt);updatePool(smoke,dt);
  for(const ring of rings)if(ring.life>0){ring.life=Math.max(0,ring.life-dt);ring.mesh.scale.setScalar(1+(1-ring.life/ring.total)*(ring.radius-1));ring.mesh.material.opacity=ring.life/ring.total*.6;ring.mesh.visible=ring.life>0;}
  if(debrisActive){debrisActive=false;for(let i=0;i<pieces.length;i++){const p=pieces[i];p.life=Math.max(0,p.life-dt);if(p.life>0){debrisActive=true;p.vy-=19*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;if(p.y<p.floor){p.y=p.floor;p.vy=Math.abs(p.vy)*.22;p.vx*=.94;p.vz*=.94;}dummy.position.set(p.x,p.y,p.z);dummy.rotation.set(p.life*p.spin,p.life*2,0);dummy.scale.setScalar(p.size*Math.min(1,p.life));}else dummy.scale.setScalar(0);dummy.updateMatrix();debris.setMatrixAt(i,dummy.matrix);}debris.instanceMatrix.needsUpdate=true;}
 }};
}
